css:
/* Icon card grid: a centred heading and intro, then cards of icon, title and text, three across. */
[data-bz-node="icg-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="icon-card-grid"] .bz-block { padding-block: 0; }
[data-bz-section="icon-card-grid"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #000; }
[data-bz-section="icon-card-grid"] [data-bz-node="icg-intro"] .bz-text p { margin: 14px 0 0; text-align: center; font: 400 1.175rem / 1.4 var(--font-body); color: #333; max-width: none; }
[data-bz-section="icon-card-grid"] [data-bz-node="icg-row"] { margin-top: 62px; row-gap: 26px; }
[data-bz-section="icon-card-grid"] .bz-figure { margin: 0; display: flex; justify-content: center; }
[data-bz-section="icon-card-grid"] .bz-figure img { width: auto; max-width: 100%; height: auto; border-radius: 0; }
[data-bz-section="icon-card-grid"] h3 { margin: 22px 0 0; text-align: center; white-space: pre-line; font: 700 1.5rem / 1.18 var(--font-heading); color: var(--accent); letter-spacing: 0; }
[data-bz-section="icon-card-grid"] [data-bz-node^="icg-desc"] .bz-text p { margin: 20px auto 0; text-align: center; font: 400 0.95rem / 1.46 var(--font-body); color: #333; max-width: 320px; }
@media (min-width: 1400px) { [data-bz-section="icon-card-grid"] [data-bz-node^="icg-desc"] .bz-text p { white-space: pre-line; max-width: none; } }
@media (max-width: 1100px) { [data-bz-section="icon-card-grid"] [data-bz-node="icg-row"] > .bz-col { grid-column: span 6; } }
@media (max-width: 640px) { [data-bz-section="icon-card-grid"] [data-bz-node="icg-row"] > .bz-col { grid-column: 1 / -1; } [data-bz-section="icon-card-grid"] h2 { font-size: 1.5rem; } }
